                unsigned int *dst = (unsigned int *)end;
                unsigned int second = src[1];
                unsigned int first = src[0];
                dst[0] = first;
                {
                    unsigned int third = src[2];
                    dst[1] = second;
                    dst[2] = third;
                }
            }
